text(await tools.exec_command({cmd:"$b3Workspace = [IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')
$b3Manifests = @((Get-Content docs/reviews/b3/early-verification-manifest.json -Raw | ConvertFrom-Json), (Get-Content docs/reviews/b3/runtime-originals-manifest.json -Raw | ConvertFrom-Json))
$b3Hashes = @{}
foreach ($b3Manifest in $b3Manifests) { foreach ($b3Member in $b3Manifest.members) { $b3Hashes[$b3Member.source] = $b3Member.sha256 } }
$b3Folders = @('docs/reviews/b3/local-required-1','docs/reviews/b3/local-required-2','docs/reviews/b3/local-required-3','docs/reviews/b3/local-required-4','docs/reviews/b3/local-integration-5','docs/reviews/b3/local-recovery','docs/reviews/b3/local-recovery-2','packages/conformance/conformance-results')
$b3Receipt = @()
foreach ($b3Folder in $b3Folders) {
 $b3Target = [IO.Path]::GetFullPath((Join-Path $b3Workspace $b3Folder))
 if (-not $b3Target.StartsWith($b3Workspace+'\',[StringComparison]::Ordinal)) { throw '生成目录越过当前工作树' }
 $b3Items = @(Get-Item -LiteralPath $b3Target) + @(Get-ChildItem -LiteralPath $b3Target -Recurse -Force)
 if ($b3Items | Where-Object { $_.Attributes -band [IO.FileAttributes]::ReparsePoint }) { throw '生成目录有重解析点，停止' }
 foreach ($b3Item in $b3Items) {
  if ($b3Item.FullName -cne $b3Target -and -not $b3Item.FullName.StartsWith($b3Target+'\',[StringComparison]::Ordinal)) { throw '生成对象越界' }
  if (-not $b3Item.PSIsContainer) {
   $b3Relative = $b3Item.FullName.Substring($b3Workspace.Length+1).Replace('\','/')
   if (-not $b3Hashes.ContainsKey($b3Relative) -or (Get-FileHash -LiteralPath $b3Item.FullName -Algorithm SHA256).Hash.ToLowerInvariant() -cne $b3Hashes[$b3Relative]) { throw '原件归档哈希不符，停止' }
  }
 }
 foreach ($b3Child in @(Get-ChildItem -LiteralPath $b3Target -Force)) {
  if ($b3Folder -like 'docs/reviews/b3/*' -and $b3Child.Name -eq 'results.json') { continue }
  $b3ChildPath=[IO.Path]::GetFullPath($b3Child.FullName)
  if ([IO.Path]::GetDirectoryName($b3ChildPath) -cne $b3Target) { throw '删除目标边界不符' }
  if ($b3Child.PSIsContainer) { Remove-Item -LiteralPath $b3ChildPath -Recurse -ErrorAction Stop } else { Remove-Item -LiteralPath $b3ChildPath -ErrorAction Stop }
 }
 if ($b3Folder -eq 'packages/conformance/conformance-results') { [IO.Directory]::Delete($b3Target,$false) }
 $b3Receipt += [ordered]@{ path=$b3Folder; reparseCount=0; archiveMembersVerified=$true; removedGeneratedCopies=$true; retained=if ($b3Folder -like 'docs/reviews/b3/*') {'results.json'} else {'压缩包中的三份 conformance 原件'} }
 [ordered]@{ archives=@($b3Manifests.archive); indexBytesVerified=$true; scope='仅本任务生成的原件副本；不改共享缓存、业务或历史证据'; results=$b3Receipt } | ConvertTo-Json -Depth 5 | Set-Content docs/reviews/b3/artifact-compaction.json -Encoding utf8
}
Write-Output "原件已压缩保全，定向收尾生成目录：$($b3Receipt.Count)"",login:false,max_output_tokens:1600,yield_time_ms:1000}));
